import{_ as o,o as t,c as a,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Whats new in MicroCeph?","description":"","frontmatter":{"title":"Whats new in MicroCeph?","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","MicroCeph","Distributed Storage","Cloud Computing","Storage Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/What_s_new_in_MicroCeph.md","filePath":"posts/2025/What_s_new_in_MicroCeph.md","lastUpdated":1780459816000}'),i={name:"posts/2025/What_s_new_in_MicroCeph.md"};function n(s,r,l,h,g,c){return t(),a("div",null,[...r[0]||(r[0]=[e('<h3 id="会议纪要-microceph-最新进展讨论" tabindex="-1"><strong>会议纪要：MicroCeph 最新进展讨论</strong> <a class="header-anchor" href="#会议纪要-microceph-最新进展讨论" aria-label="Permalink to &quot;**会议纪要：MicroCeph 最新进展讨论**&quot;">​</a></h3><h4 id="_1-会议概述" tabindex="-1"><strong>1. 会议概述</strong> <a class="header-anchor" href="#_1-会议概述" aria-label="Permalink to &quot;**1. 会议概述**&quot;">​</a></h4><p>本次会议主要讨论了基于Ceph的轻量化部署方案MicroCeph的最新进展，包括其核心设计理念、新增功能、技术优化及未来路线图。参会者对MicroCeph的简化部署、多协议支持及Intel QAT集成表现出浓厚兴趣。</p><h4 id="_2-主要议题与讨论内容" tabindex="-1"><strong>2. 主要议题与讨论内容</strong> <a class="header-anchor" href="#_2-主要议题与讨论内容" aria-label="Permalink to &quot;**2. 主要议题与讨论内容**&quot;">​</a></h4><h5 id="_1-microceph-核心定位" tabindex="-1"><strong>(1) MicroCeph 核心定位</strong> <a class="header-anchor" href="#_1-microceph-核心定位" aria-label="Permalink to &quot;**(1) MicroCeph 核心定位**&quot;">​</a></h5><ul><li><strong>Micro的含义</strong>：并非指规模小，而是强调Day 2运维的简化，如两命令部署集群。</li><li><strong>目标用户</strong>：面向非专业存储团队，支持快速在边缘设备（如树莓派、桌面机）部署真实Ceph集群。</li><li><strong>关键技术</strong>：Snap容器化封装，跨平台支持；初始支持RBD和CephFS，后续扩展RGW及静态加密功能。</li></ul><h5 id="_2-新增功能" tabindex="-1"><strong>(2) 新增功能</strong> <a class="header-anchor" href="#_2-新增功能" aria-label="Permalink to &quot;**(2) 新增功能**&quot;">​</a></h5><ul><li><strong>RBD Mirror 简化配置</strong>：通过导出/导入字符串实现跨集群复制配置，隐藏底层复杂状态机逻辑。</li><li><strong>Intel QAT（Quick Assist Technology）集成</strong>：支持压缩卸载，显著提升性能并节省存储空间；扩展功能：RGW的服务器端加密。</li></ul><h5 id="_3-未来计划-2024年路线图" tabindex="-1"><strong>(3) 未来计划（2024年路线图）</strong> <a class="header-anchor" href="#_3-未来计划-2024年路线图" aria-label="Permalink to &quot;**(3) 未来计划（2024年路线图）**&quot;">​</a></h5><ul><li><strong>CephFS Mirror 管理</strong>：单命令启用文件系统级复制。</li><li><strong>RGW 多站点支持</strong>：分阶段交付，优先实现双站点配置。</li><li><strong>SMB 协议支持</strong>：面向SOHO场景，打造Ceph存储设备。</li><li><strong>Dashboard 自动化</strong>：简化管理界面启用流程，如自动生成SSL证书。</li></ul><h4 id="_3-关键决策与行动项" tabindex="-1"><strong>3. 关键决策与行动项</strong> <a class="header-anchor" href="#_3-关键决策与行动项" aria-label="Permalink to &quot;**3. 关键决策与行动项**&quot;">​</a></h4><ul><li><strong>短期优先级</strong>：完成CephFS Mirror的简化命令集成；推进RGW多站点的架构设计。</li><li><strong>长期优化</strong>：调研SMB协议的兼容性与性能调优方案；开发Dashboard一键启用功能。</li></ul><h4 id="_4-遗留问题与后续计划" tabindex="-1"><strong>4. 遗留问题与后续计划</strong> <a class="header-anchor" href="#_4-遗留问题与后续计划" aria-label="Permalink to &quot;**4. 遗留问题与后续计划**&quot;">​</a></h4><ul><li><strong>技术验证</strong>：进一步测试Intel QAT在混合云场景下的压缩效率。</li><li><strong>用户反馈收集</strong>：通过GitHub Action等渠道评估CI/CD场景的部署体验。</li><li><strong>社区协作</strong>：与Canonical合作优化Snap打包的跨平台兼容性。</li></ul><h4 id="_5-附录-保留关键词-中英对照" tabindex="-1"><strong>5. 附录：保留关键词（中英对照）</strong> <a class="header-anchor" href="#_5-附录-保留关键词-中英对照" aria-label="Permalink to &quot;**5. 附录：保留关键词（中英对照）**&quot;">​</a></h4><ul><li><strong>核心组件</strong>：OSD、MON、MDS、PG、RADOS、librados、BlueStore</li><li><strong>协议/接口</strong>：RBD、CephFS、RGW、RESTful API、iSCSI、NFS、POSIX</li><li><strong>技术特性</strong>：Erasure Coding、CRUSH Algorithm、Thin Provisioning、Load Balancing</li></ul><p><strong>会议结束时间</strong>：讨论持续约40分钟，后续将通过邮件同步RGW多站点设计文档。</p><p>[Applause]</p>',18)])])}const d=o(i,[["render",n]]);export{_ as __pageData,d as default};
